enum Curriculum {
    static let allDays: [CourseDay] = [
        makeDay(1, "Meet, move, and notice", "சந்திப்பு, நகர்வு", "main / tum / woh + go and come", "Catch who is moving and where the sentence is heading.", [
            prompt("office-jaana", "kal office jaana hai", "நாளை அலுவலகம் செல்ல வேண்டும்", "I have to go to the office tomorrow.", "jaana", "kal + place + jaana hai", "The ending hai often carries a need or plan.", "What is the speaker's plan?", ["Go to the office tomorrow", "Come home now", "Eat at the office", "Call a friend"], "Go to the office tomorrow", .meaning, .gist),
            prompt("ghar-aa-rahi", "main ghar aa rahi hoon", "நான் வீட்டிற்கு வந்து கொண்டிருக்கிறேன்", "I am coming home.", "aana", "main + aa rahi hoon", "The sound aa- points to aana, to come.", "Which action is happening now?", ["Coming home", "Going to work", "Drinking water", "Waiting outside"], "Coming home", .meaning, .verbFamilies),
            prompt("kya-hua", "kya hua?", "என்ன நடந்தது?", "What happened?", "hona", "kya + hua", "hua is a past form of hona, to happen / be.", "What does the question ask?", ["What happened?", "Where are you going?", "What do you want?", "Who came?"], "What happened?", .meaning, .anchors),
