        ], roleplay("day1-home", "At home", "Your friend is checking if you are on your way home.", "ghar aa rahi ho?", "நீ வீட்டிற்கு வருகிறாயா?", "Are you coming home?", ["Haan, bas aa rahi hoon.", "Nahi, paani chahiye.", "Kal office gaya.", "Kya hua?"], "Haan, bas aa rahi hoon.", "ஆம், வந்து கொண்டிருக்கிறேன்.", "Yes, I am on my way.", "Listen for aa- in aana and rahi hoon for an action happening now.") ),
        makeDay(2, "Home anchors", "வீட்டு முக்கிய சொற்கள்", "ghar, room, darwaaza, andar, baahar", "Recognize the place and direction before translating the rest.", [
            prompt("d2-1", "woh ghar ke andar hai", "அவர் வீட்டிற்குள் இருக்கிறார்", "They are inside the house.", "ghar", "ghar + ke andar", "andar means inside; it often follows a place.", "Where is the person?", ["Inside the house", "Outside the office", "At the station", "In the market"], "Inside the house", .meaning, .anchors),
            prompt("d2-2", "darwaaza band kar do", "கதவை மூடி விடுங்கள்", "Please close the door.", "karna", "thing + action + kar do", "kar do is a friendly spoken request to do something.", "What should happen to the door?", ["Close it", "Open it", "Paint it", "Move it"], "Close it", .reply, .response),
            prompt("d2-3", "main baahar jaa rahi hoon", "நான் வெளியே செல்கிறேன்", "I am going outside.", "jaana", "main + baahar + jaa rahi hoon", "baahar means outside; jaa- is the go family.", "Which place clue did you hear?", ["baahar", "andar", "ghar", "room"], "baahar", .anchor, .anchors),
            prompt("d2-4", "room mein koi hai", "அறையில் யாரோ இருக்கிறார்", "Someone is in the room.", "hona", "place + mein + hai", "hai marks a present state or location.", "What is the time clue?", ["Present / now", "Past", "Future", "A request"], "Present / now", .timeClue, .gist)
        ], roleplay("day2-door", "At the door", "Your housemate asks why the door is still open.", "darwaaza khula hai?", "கதவு திறந்திருக்கிறதா?", "Is the door open?", ["Haan, abhi band kar deti hoon.", "Kal office jaana hai.", "Mujhe chai chahiye.", "Woh ghar gaya."], "Haan, abhi band kar deti hoon.", "ஆம், இப்போது மூடுகிறேன்.", "Yes, I will close it now.", "A short reply can carry the whole context; listen for abhi (now) and band (closed).")),
        makeDay(3, "Eat, drink, and ask", "சாப்பாடு, குடிப்பு, கேட்பது", "khaana, peena, chahiye, thoda", "Ask for food or drink and catch whether someone already ate.", [
            prompt("khana-khaaya", "maine khaana khaaya", "நான் சாப்பாடு சாப்பிட்டேன்", "I ate food.", "khaana", "maine + thing + khaaya", "khaaya is a common past form in the khaana family.", "Has the speaker eaten?", ["Yes, already", "No, tomorrow", "They are asking for water", "They are leaving"], "Yes, already", .timeClue, .gist),
            prompt("chai-peena", "chai peena hai", "தேநீர் குடிக்க வேண்டும்", "I have to drink tea / need to have tea.", "peena", "thing + peena hai", "peena is to drink; hai makes the need/plan frame.", "What is the intent?", ["Drink tea", "Cook rice", "Buy a ticket", "Go outside"], "Drink tea", .meaning, .verbFamilies),
            prompt("d3-3", "mujhe thoda khaana chahiye", "எனக்கு கொஞ்சம் சாப்பாடு வேண்டும்", "I need a little food.", "chahiye", "mujhe + amount + thing + chahiye", "thoda softens a request: a little.", "Which word signals a small amount?", ["thoda", "mujhe", "khaana", "chahiye"], "thoda", .anchor, .anchors),
            prompt("d3-4", "tumne chai pi?", "நீ தேநீர் குடித்தாயா?", "Did you drink tea?", "peena", "tumne + thing + pi", "pi is a short past sound for peena.", "Is this about past or future?", ["Past", "Future", "Present action", "A location"], "Past", .timeClue, .gist)
        ], roleplay("day3-cafe", "At a cafe", "A friend asks what you want after work.", "kya logi?", "என்ன எடுத்துக்கொள்வாய்?", "What will you have?", ["Mujhe chai chahiye.", "Main ghar jaa rahi hoon.", "Darwaaza band hai.", "Kal aayega."], "Mujhe chai chahiye.", "எனக்கு தேநீர் வேண்டும்.", "I would like tea.", "chahiye is a high-value request frame; it is more useful than memorizing a full menu.")),
        makeDay(4, "Morning routine", "காலை வழக்கம்", "uthna, jaana, karna, abhi", "Follow a short routine by spotting the action and the now clue.", [
            prompt("d4-1", "abhi uth rahi hoon", "இப்போது எழுந்து கொண்டிருக்கிறேன்", "I am getting up now.", "uthna", "abhi + action rahi hoon", "abhi means now; rahi hoon marks a current action for a female speaker.", "When is this happening?", ["Now", "Yesterday", "Tomorrow", "Never"], "Now", .timeClue, .gist),
            prompt("d4-2", "main nahaane jaa rahi hoon", "நான் குளிக்கச் செல்கிறேன்", "I am going to bathe.", "jaana", "main + action + jaa rahi hoon", "jaa rahi hoon tells you the speaker is leaving toward an action.", "Which verb family carries the movement?", ["jaana", "aana", "bolna", "lena"], "jaana", .anchor, .verbFamilies),
            prompt("d4-3", "nashta kar liya?", "காலை உணவு சாப்பிட்டுவிட்டாயா?", "Did you have breakfast?", "karna", "thing + kar liya", "kar liya often means completed / got done.", "What is being checked?", ["Breakfast is done", "A trip is planned", "The door is open", "A message arrived"], "Breakfast is done", .meaning, .gist),
            prompt("d4-4", "aaj kaam karna hai", "இன்று வேலை செய்ய வேண்டும்", "I have to work today.", "karna", "aaj + kaam + karna hai", "aaj means today and karna hai carries a plan or need.", "What must happen today?", ["Work", "Travel", "Eat", "Call"], "Work", .meaning, .response)
        ], roleplay("day4-morning", "Before work", "Your friend asks if you are ready to leave.", "abhi nikalogi?", "இப்போது கிளம்புவாயா?", "Will you leave now?", ["Haan, bas nikal rahi hoon.", "Maine khaana khaaya.", "Mujhe paani chahiye.", "Woh room mein hai."], "Haan, bas nikal rahi hoon.", "ஆம், இப்போது கிளம்புகிறேன்.", "Yes, I am just leaving.", "bas means just / about to; it makes the reply sound natural.")),
        makeDay(5, "People around you", "உங்களைச் சுற்றியவர்கள்", "mummy, papa, dost, woh, sab", "Track who did the action when family and friends enter the sentence.", [
            prompt("d5-1", "woh dost ke saath gaya", "அவர் நண்பருடன் சென்றார்", "They went with a friend.", "jaana", "woh + person + ke saath + gaya", "gaya is a common past form in the go family.", "Who went with the friend?", ["They / he", "I", "You", "Nobody"], "They / he", .meaning, .gist),
            prompt("d5-2", "mummy ghar par hai", "அம்மா வீட்டில் இருக்கிறார்", "Mom is at home.", "hona", "person + place + par hai", "par means at / on a place.", "Where is mom?", ["At home", "At work", "Outside", "On the way"], "At home", .anchor, .anchors),
            prompt("d5-3", "papa ne phone kiya", "அப்பா தொலைபேசியில் அழைத்தார்", "Dad called.", "karna", "papa ne + phone kiya", "kiya is the past form learners will hear with many actions.", "What happened?", ["Dad called", "Dad came tomorrow", "Dad needs tea", "Dad is outside"], "Dad called", .meaning, .verbFamilies),
            prompt("d5-4", "sab log aa rahe hain", "எல்லோரும் வந்து கொண்டிருக்கிறார்கள்", "Everyone is coming.", "aana", "sab + aa rahe hain", "rahe hain signals a group action happening now.", "What are everyone doing?", ["Coming", "Going", "Eating", "Waiting"], "Coming", .timeClue, .gist)
        ], roleplay("day5-family", "Family call", "A family member asks if your friend has arrived.", "tumhara dost aaya?", "உன் நண்பர் வந்தாரா?", "Did your friend arrive?", ["Haan, abhi aaya hai.", "Kal office jaana hai.", "Mujhe chai chahiye.", "Main baahar jaa rahi hoon."], "Haan, abhi aaya hai.", "ஆம், இப்போது வந்துவிட்டார்.", "Yes, they just arrived.", "aaya is the past sound for aana; abhi tells you it was just now.")),
        makeDay(6, "Office and everyday work", "அலுவலகம் மற்றும் வேலை", "kaam, office, meeting, bhejna", "Understand the rough point of a normal work update.", [
            prompt("d6-1", "office mein meeting hai", "அலுவலகத்தில் கூட்டம் இருக்கிறது", "There is a meeting at the office.", "office", "place + mein + event hai", "mein means in / at; the place often comes before the event.", "What is at the office?", ["A meeting", "A train", "Dinner", "A friend"], "A meeting", .meaning, .anchors),
            prompt("d6-2", "message bhejna hai", "செய்தி அனுப்ப வேண்டும்", "I have to send a message.", "bhejna", "thing + bhejna hai", "The hai frame can carry an obligation without saying I.", "What needs to happen?", ["Send a message", "Read a book", "Buy food", "Go home"], "Send a message", .meaning, .response),
            prompt("d6-3", "main kaam kar rahi hoon", "நான் வேலை செய்து கொண்டிருக்கிறேன்", "I am working.", "karna", "main + kaam kar rahi hoon", "kaam is work; kar rahi hoon means doing now.", "Which anchor means work?", ["kaam", "kal", "ghar", "paani"], "kaam", .anchor, .anchors),
            prompt("d6-4", "woh file le gaya", "அவர் கோப்பை எடுத்துச் சென்றார்", "They took the file away.", "lena", "woh + thing + le gaya", "le gaya combines take + went away; hear the le- sound.", "Which action is closest?", ["Took away", "Gave back", "Opened", "Spoke"], "Took away", .meaning, .verbFamilies)
        ], roleplay("day6-office", "A work update", "A teammate asks whether the message has been sent.", "message bheja?", "செய்தி அனுப்பிவிட்டாயா?", "Did you send the message?", ["Haan, bhej diya.", "Main ghar aa rahi hoon.", "Mujhe paani chahiye.", "Kal movie dekhenge."], "Haan, bhej diya.", "ஆம், அனுப்பிவிட்டேன்.", "Yes, I sent it.", "diya is a useful completed-action sound; it appears with many everyday verbs.")),
        makeDay(7, "Week 1: anchor checkpoint", "முதல் வார சோதனை", "mixed home, food, people, work", "Use anchors first: identify the action, place, and time before worrying about every word.", [
            prompt("d7-1", "kal dost ke ghar jaana hai", "நாளை நண்பரின் வீட்டிற்குச் செல்ல வேண்டும்", "I have to go to my friend's house tomorrow.", "jaana", "kal + place + jaana hai", "Place plus jaana is enough to catch this plan.", "Which plan is correct?", ["Go to a friend's house tomorrow", "Eat at the office now", "Come home yesterday", "Call dad later"], "Go to a friend's house tomorrow", .meaning, .gist),
            prompt("d7-2", "maine chai pi aur kaam kiya", "நான் தேநீர் குடித்து வேலை செய்தேன்", "I drank tea and worked.", "karna", "maine + past action + aur + past action", "aur means and; it links two completed actions.", "What is the time frame?", ["Past", "Now", "Future", "Question only"], "Past", .timeClue, .gist),
            prompt("d7-3", "woh kya bol raha hai?", "அவர் என்ன பேசுகிறார்?", "What is he saying?", "bolna", "woh + kya + bol raha hai", "bol means say/speak; raha hai signals an action in progress.", "Which verb family should you choose?", ["bolna", "peena", "lena", "jaana"], "bolna", .anchor, .verbFamilies),
            prompt("d7-4", "mujhe ghar jaana hai", "எனக்கு வீட்டிற்குச் செல்ல வேண்டும்", "I need to go home.", "jaana", "mujhe + place + jaana hai", "This is a high-frequency need/intent frame.", "What does the speaker need to do?", ["Go home", "Drink tea", "Send a file", "Open the door"], "Go home", .reply, .response)
        ], roleplay("day7-checkpoint", "Quick check-in", "Your friend asks what you need to do next.", "ab kya karna hai?", "இப்போது என்ன செய்ய வேண்டும்?", "What do you have to do now?", ["Mujhe ghar jaana hai.", "Kal papa aaye.", "Darwaaza band hai.", "Maine chai pi."], "Mujhe ghar jaana hai.", "நான் வீட்டிற்குச் செல்ல வேண்டும்.", "I need to go home.", "A useful response can be a complete intent frame even when the question is fast.")),
        makeDay(8, "Time words", "நேரச் சொற்கள்", "aaj, kal, abhi, baad mein", "Use time words to orient a sentence before decoding the verb.", [
            prompt("d8-1", "aaj movie dekhna hai", "இன்று படம் பார்க்க வேண்டும்", "I have to watch a movie today.", "dekhna", "aaj + movie + dekhna hai", "aaj means today; the rest is a plan.", "When is the movie plan?", ["Today", "Yesterday", "Right now only", "Next month"], "Today", .timeClue, .anchors),
            prompt("d8-2", "kal aayega", "அவர் நாளை வருவார்", "He will come tomorrow.", "aana", "kal + aayega", "aayega is future for the come family.", "What is the time clue?", ["Future", "Past", "Present", "A request"], "Future", .timeClue, .gist),
            prompt("d8-3", "abhi nahi, baad mein", "இப்போது இல்லை, பிறகு", "Not now, later.", "baad mein", "abhi nahi + baad mein", "baad mein is a very reusable later marker.", "When should it happen?", ["Later", "Yesterday", "Now", "Never"], "Later", .anchor, .anchors),
            prompt("d8-4", "maine kal dekha", "நான் நேற்று பார்த்தேன்", "I saw it yesterday.", "dekhna", "maine + kal + dekha", "kal can mean yesterday or tomorrow; the verb form supplies the clue.", "What does the past form tell you here?", ["Saw yesterday", "Will see tomorrow", "Is seeing now", "Must watch"], "Saw yesterday", .meaning, .gist)
        ], roleplay("day8-time", "Making a plan", "A friend asks whether to meet today or later.", "aaj milna hai?", "இன்று சந்திக்க வேண்டுமா?", "Should we meet today?", ["Nahi, baad mein milte hain.", "Maine phone liya.", "Woh office mein hai.", "Khaana kha rahi hoon."], "Nahi, baad mein milte hain.", "இல்லை, பிறகு சந்திப்போம்.", "No, let's meet later.", "Time markers are your first filter: aaj, kal, abhi, baad mein.")),
        makeDay(9, "Getting around", "பயணம் மற்றும் போக்குவரத்து", "auto, bus, train, station, pahunchna", "Follow a simple travel update and notice arrival versus departure.", [
            prompt("d9-1", "auto se office jaa rahi hoon", "ஆட்டோவில் அலுவலகம் செல்கிறேன்", "I am going to the office by auto.", "jaana", "transport se + place + jaa rahi hoon", "se can mean by / via in travel contexts.", "How is the speaker travelling?", ["By auto", "By train", "On foot", "By flight"], "By auto", .anchor, .anchors),
            prompt("d9-2", "train aa gayi", "ரயில் வந்து விட்டது", "The train has arrived.", "aana", "train + aa gayi", "aa gayi is a completed feminine/inanimate arrival sound.", "What happened to the train?", ["It arrived", "It left", "It is delayed tomorrow", "It is inside"], "It arrived", .meaning, .verbFamilies),
            prompt("d9-3", "station pahunch gaye", "நிலையத்தை அடைந்து விட்டோம்", "We reached the station.", "pahunchna", "place + pahunch gaye", "gaye can signal a completed movement with we/they.", "What is complete?", ["Reaching the station", "Buying a ticket", "Calling a friend", "Eating food"], "Reaching the station", .timeClue, .gist),
            prompt("d9-4", "kitne baje nikloge?", "எத்தனை மணிக்கு கிளம்புவாய்?", "What time will you leave?", "nikalna", "kitne baje + future question", "kitne baje asks at what time.", "What is being asked?", ["Departure time", "Ticket price", "Destination", "Food choice"], "Departure time", .meaning, .response)
        ], roleplay("day9-travel", "On the way", "A friend asks if you have reached the station.", "station pahunchi?", "நிலையத்தை அடைந்தாயா?", "Did you reach the station?", ["Haan, abhi pahunchi.", "Kal aayega.", "Mujhe chai chahiye.", "Woh file le gaya."], "Haan, abhi pahunchi.", "ஆம், இப்போது அடைந்தேன்.", "Yes, I just reached it.", "pahunch- is a useful travel anchor; abhi makes the timing immediate.")),
        makeDay(10, "Shopping talk", "கடை உரையாடல்", "lena, dena, paise, kitna, chahiye", "Ask for an item, understand a price question, and respond simply.", [
            prompt("d10-1", "yeh lena hai", "இதை எடுக்க வேண்டும்", "I want / need to take this.", "lena", "yeh + lena hai", "lena means take / get; context decides the exact English.", "What action is planned?", ["Take / get this", "Give this away", "Watch this", "Eat this"], "Take / get this", .meaning, .verbFamilies),
            prompt("d10-2", "kitne paise hue?", "எவ்வளவு பணம் ஆனது?", "How much money is it?", "hona", "kitne paise + hue", "hue asks what the amount came to.", "What does the question ask?", ["The price", "The time", "The location", "The size"], "The price", .anchor, .response),
            prompt("d10-3", "mujhe yeh nahi chahiye", "எனக்கு இது வேண்டாம்", "I do not want this.", "chahiye", "mujhe + thing + nahi chahiye", "nahi makes the request negative.", "Does the speaker want it?", ["No", "Yes", "Maybe tomorrow", "Already bought it"], "No", .meaning, .gist),
            prompt("d10-4", "paise de do", "பணத்தை கொடுத்து விடுங்கள்", "Please give the money.", "dena", "thing + de do", "de do is a direct but common request to give something.", "Which verb means give?", ["dena", "lena", "jaana", "bolna"], "dena", .anchor, .verbFamilies)
        ], roleplay("day10-shop", "At a shop", "The seller asks if you want the blue bag.", "yeh bag logi?", "இந்த பையை எடுத்துக்கொள்வாயா?", "Will you take this bag?", ["Haan, yeh lena hai.", "Main office jaa rahi hoon.", "Kal train aa gayi.", "Kya hua?"], "Haan, yeh lena hai.", "ஆம், இதை எடுத்துக்கொள்கிறேன்.", "Yes, I will take this.", "lena is the take/get family; chahiye is useful when you want to soften the request.")),
        makeDay(11, "Useful requests", "பயனுள்ள வேண்டுகோள்கள்", "please, thoda, sakte ho, dena", "Make and understand polite everyday requests without full grammar study.", [
            prompt("d11-1", "thoda ruk sakte ho?", "கொஞ்சம் காத்திருக்க முடியுமா?", "Can you wait a little?", "rukna", "thoda + action + sakte ho", "sakte ho frames a can-you request.", "What is the request?", ["Wait a little", "Speak loudly", "Come tomorrow", "Give water"], "Wait a little", .reply, .response),
