        ], roleplay("day14-checkpoint", "Busy day", "A friend asks whether you can talk now.", "abhi baat kar sakti ho?", "இப்போது பேச முடியுமா?", "Can you talk now?", ["Nahi, baad mein baat karte hain.", "Maine khaana khaaya.", "Woh station pahunch gaya.", "Mujhe chai chahiye."], "Nahi, baad mein baat karte hain.", "இல்லை, பிறகு பேசுவோம்.", "No, we can talk later.", "The goal is to follow the decision in context, not translate every filler word.")),
        makeDay(15, "Past actions", "கடந்த செயல்கள்", "kiya, gaya, aaya, liya", "Recognize a completed action even when the verb changes shape.", [
