        ], roleplay("day15-past", "After an errand", "Someone asks whether you bought the item.", "saamaan liya?", "பொருளை எடுத்தாயா?", "Did you get the item?", ["Haan, le liya.", "Kal jaaungi.", "Mujhe rest chahiye.", "Woh aa raha hai."], "Haan, le liya.", "ஆம், எடுத்துவிட்டேன்.", "Yes, I got it.", "le liya is a compact completion frame: took/got it.")),
        makeDay(16, "Happening right now", "இப்போது நடப்பது", "raha, rahi, rahe, abhi", "Hear the action that is in progress and the person doing it.", [
