            prompt("d18-1", "kahan jaa rahe ho?", "எங்கே செல்கிறாய்?", "Where are you going?", "jaana", "kahan + jaa rahe ho", "kahan asks where.", "What information is requested?", ["Place", "Time", "Reason", "Person"], "Place", .anchor, .response),
