        ], roleplay("day19-boundary", "A small boundary", "A friend offers a spicy dish you do not want.", "yeh khaogi?", "இதைச் சாப்பிடுவாயா?", "Will you eat this?", ["Nahi, yeh nahi chahiye.", "Haan, kal aaungi.", "Woh ghar mein hai.", "Maine message bheja."], "Nahi, yeh nahi chahiye.", "இல்லை, இது வேண்டாம்.", "No, I do not want this.", "nahi chahiye is a practical, polite boundary in everyday speech.")),
        makeDay(20, "Connectors and messy speech", "இணைப்புச் சொற்கள்", "aur, lekin, kyunki, phir, bas", "Keep the main point while fillers and connectors make the sentence longer.", [
