            prompt("d20-2", "pehle kaam, phir movie", "முதலில் வேலை, பிறகு படம்", "Work first, then a movie.", "karna", "pehle + action, phir + action", "pehle means first; phir means then.", "What comes first?", ["Work", "Movie", "Dinner", "Travel"], "Work", .anchor, .anchors),
            prompt("d20-3", "main nahi aa rahi kyunki thak gayi hoon", "நான் வரவில்லை, ஏனெனில் சோர்வாக இருக்கிறேன்", "I am not coming because I am tired.", "aana", "nahi + action + kyunki + reason", "kyunki introduces the reason.", "Why is the speaker not coming?", ["They are tired", "They are at work", "They need water", "They are travelling"], "They are tired", .meaning, .gist),
            prompt("d20-4", "bas ek minute", "ஒரு நிமிடம் மட்டும்", "Just one minute.", "bas", "bas + amount", "bas can mean just / that's all and is common in quick replies.", "How long?", ["Just one minute", "A long time", "Tomorrow", "Not at all"], "Just one minute", .reply, .response)
        ], roleplay("day20-connectors", "Changing a plan", "You need to explain why you are late.", "itni der kyun?", "இவ்வளவு நேரம் ஏன்?", "Why so late?", ["Traffic tha, isliye late.", "Mujhe chai chahiye.", "Kal movie dekhi.", "Woh paani de raha hai."], "Traffic tha, isliye late.", "போக்குவரத்து இருந்தது, அதனால் தாமதம்.", "There was traffic, so I am late.", "isliye means so / therefore; keep the reason and result together.")),
        makeDay(21, "Week 3: time and tense checkpoint", "மூன்றாம் வார சோதனை", "past vs now vs future in one exchange", "Track when actions happen while the words get shorter and faster.", [
            prompt("d21-1", "kal gayi thi, aaj ghar par hoon", "நேற்று சென்றிருந்தேன், இன்று வீட்டில் இருக்கிறேன்", "I went yesterday; today I am at home.", "jaana", "past + aaj + present", "The time words do much of the work here.", "Where is the speaker today?", ["At home", "At the office", "At a cafe", "On a train"], "At home", .meaning, .gist),
            prompt("d21-2", "abhi kha rahi hoon, baad mein bolungi", "இப்போது சாப்பிடுகிறேன், பிறகு பேசுவேன்", "I am eating now; I will talk later.", "khaana", "abhi + current, baad mein + future", "Two time frames can be chained in one natural line.", "When will she talk?", ["Later", "Now", "Yesterday", "Never"], "Later", .timeClue, .gist),
            prompt("d21-3", "woh kal aayega, phir dekhenge", "அவர் நாளை வருவார், பிறகு பார்ப்போம்", "He will come tomorrow; then we will see.", "aana", "future + phir + future", "dekhenge can mean we will see / decide then.", "What is the rough plan?", ["Wait for him, then decide", "Eat now", "Go home yesterday", "Send a message"], "Wait for him, then decide", .meaning, .response),
