        ], roleplay("day21-checkpoint", "Three time frames", "A friend asks what you are doing and what you will do later.", "abhi kya kar rahi ho, baad mein?", "இப்போது என்ன செய்கிறாய், பிறகு?", "What are you doing now, and later?", ["Abhi kha rahi hoon, baad mein bolungi.", "Kal office gayi.", "Mujhe paise chahiye.", "Darwaaza band karo."], "Abhi kha rahi hoon, baad mein bolungi.", "இப்போது சாப்பிடுகிறேன், பிறகு பேசுவேன்.", "I am eating now; I will talk later.", "Use the time words as rails; they keep a fast sentence understandable.")),
        makeDay(22, "Phone and messages", "தொலைபேசி மற்றும் செய்திகள்", "call, phone, message, dekhna, bhejna", "Understand what happened on a phone and choose a natural follow-up.", [
