            prompt("d23-3", "dawa le li?", "மருந்தை எடுத்தாயா?", "Did you take the medicine?", "lena", "thing + le li", "le li is a compact completed-action question.", "What should have been taken?", ["Medicine", "Water", "A phone", "A train"], "Medicine", .anchor, .anchors),
