            prompt("d29-3", "theek hai, baad mein baat karte hain", "சரி, பிறகு பேசுவோம்", "Okay, we will talk later.", "bolna", "theek hai + baad mein baat karte hain", "A repair can end with a calm future suggestion.", "When will they talk?", ["Later", "Now", "Yesterday", "Never"], "Later", .timeClue, .response),
