        ], roleplay("day29-rehearsal", "A real catch-up", "A friend asks whether you can talk later after a missed call.", "baad mein baat karogi?", "பிறகு பேசுவாயா?", "Will you talk later?", ["Haan, message kar dena.", "Maine kal khaaya.", "Woh station mein hai.", "Mujhe paani chahiye."], "Haan, message kar dena.", "ஆம், செய்தி அனுப்பி விடு.", "Yes, send me a message.", "A useful conversation is a series of small successful turns, not a perfect translation.")),
        makeDay(30, "Final mission: follow the point", "இறுதி பயிற்சி: கருத்தைப் பின்தொடருங்கள்", "mixed everyday conversation", "Handle a predictable short exchange, repair once, and answer with your own useful line.", [
            prompt("d30-1", "aaj office ke baad ghar aaogi ya dost ke saath jaogi?", "இன்று அலுவலகத்திற்குப் பிறகு வீட்டிற்கு வருவாயா அல்லது நண்பருடன் செல்வாயா?", "After work today, will you come home or go with a friend?", "jaana", "choice question + after work", "ya means or; catch the two possible destinations.", "What two options are offered?", ["Home or go with a friend", "Tea or water", "Yesterday or tomorrow", "Phone or message"], "Home or go with a friend", .meaning, .gist),
