    static func day(number: Int) -> CourseDay {
        allDays.first(where: { $0.number == number }) ?? allDays[0]
    }

    private static func prompt(
        _ id: String,
        _ phrase: String,
        _ tamil: String,
        _ english: String,
        _ anchor: String,
        _ pattern: String,
        _ note: String,
        _ question: String,
        _ choices: [String],
        _ correctChoice: String,
        _ mode: PromptMode,
        _ skill: SkillArea
    ) -> PhrasePrompt {
        PhrasePrompt(id: id, phrase: phrase, tamil: tamil, english: english, anchor: anchor, pattern: pattern, note: note, question: question, choices: choices, correctChoice: correctChoice, mode: mode, skill: skill)
    }

    private static func roleplay(
        _ id: String,
        _ title: String,
        _ setting: String,
        _ opening: String,
        _ openingTamil: String,
        _ openingEnglish: String,
        _ choices: [String],
        _ bestChoice: String,
        _ helpfulReplyTamil: String,
        _ helpfulReplyEnglish: String,
        _ tip: String
    ) -> RoleplayScenario {
        RoleplayScenario(id: id, title: title, setting: setting, opening: opening, openingTamil: openingTamil, openingEnglish: openingEnglish, choices: choices, bestChoice: bestChoice, helpfulReplyTamil: helpfulReplyTamil, helpfulReplyEnglish: helpfulReplyEnglish, tip: tip)
    }

    private static func makeDay(
        _ number: Int,
        _ title: String,
        _ tamilTitle: String,
        _ focus: String,
        _ outcome: String,
        _ prompts: [PhrasePrompt],
        _ roleplay: RoleplayScenario
    ) -> CourseDay {
        CourseDay(number: number, title: title, tamilTitle: tamilTitle, focus: focus, outcome: outcome, minutes: 12, prompts: prompts, roleplay: roleplay)
    }
}
